describe('Active Filters Display', () => {
    beforeEach(() => {
        cy.visit('/search'); // Adjust the URL to match the application
        cy.get('.filter-input').type('example filter'); // Simulate entering a filter
        cy.get('.filter-submit').click(); // Simulate submitting the filter
    });

    it('should display a tag for each active filter above the results', () => {
        cy.get('.active-filters').should('exist'); // Check if active filters section exists
        cy.get('.active-filters .filter-tag').should('have.length.greaterThan', 0); // Ensure there are active filter tags
        cy.get('.active-filters .filter-tag').first().should('contain', 'example filter'); // Check the content of the first filter tag
    });

    it('should not display any filter tags when no filters are applied', () => {
        cy.get('.clear-filters').click(); // Simulate clearing all filters
        cy.get('.active-filters').should('not.exist'); // Ensure active filters section does not exist
    });
});
